-- SC OPAH BY RAMZ
-- Basic source encoding (hex). This is NOT strong security/true obfuscation.
-- Keep the original source as a backup.
local encoded = ""
local decoded = {}

for i = 1, #encoded, 2 do
    local byteValue = tonumber(string.sub(encoded, i, i + 1), 16)
    if not byteValue then
        error("Invalid encoded script data")
    end
    decoded[#decoded + 1] = string.char(byteValue)
end

local source = table.concat(decoded)
local compiler = loadstring
if type(compiler) ~= "function" then
    error("loadstring is not available in this environment")
end

local chunk, compileError = compiler(source)
if not chunk then
    error(compileError)
end

return chunk()
